        const o = it.object;
        if (!opaqueOf(o, hg)) continue;
        const om = Array.isArray(o.material) ? o.material[0] : o.material;
        const ui = om && (om.depthTest === false || om.blending !== 1);
        blocker = { name: (o.name || 'mesh') + (o.isInstancedMesh ? '[inst]' : '') + '<' + ((o.parent && o.parent.name) || '?') + '>', ui: !!ui };
