      const st = __DQ.state().field.camera;
      S.slide.push(Math.abs(st.keep.slide));
      S.hero.push((__DQ.cameraFrame() || {}).heroPct || 0);
      S.pos.push([cam.position.x, cam.position.y, cam.position.z, cam.quaternion.x, cam.quaternion.y, cam.quaternion.z, cam.quaternion.w]);
      S.zoom.push(Math.abs(st.dist - st.distTarget));
