          if (i % every === 0) { try { this.sample(S); } catch (e) { S.errs++; } }
        }
      }
      __DQ.freeze(false);
      const r3 = v => +Number(v).toFixed(3);
      const mx = a => a.length ? Math.max.apply(null, a) : 0;
      const med = a => { const c = a.slice().sort((x, y) => x - y); return c.length ? c[c.length >> 1] : 0; };
